    text: 'What is digital printing and how does it differ from offset lithography?',
    options: ['They are identical processes', 'Digital printing applies ink (inkjet) or toner (laser) directly from a digital file without plates — cost-effective for short runs, variable data, and on-demand printing; offset needs plates so is more economical for large runs', 'Digital printing only works on plastic', 'Offset printing is digital; digital printing is analogue'],
    answer: '1',
    explanation: 'Digital printing: no plates — images transferred directly from file to substrate via inkjet droplets or electrostatic toner (laser). Short runs, personalisation, and quick turnaround. Offset: plates made first (setup cost) but very low per-unit cost at high volumes. Break-even typically around 500–1000 copies.',
