    text: 'What is bleed in print design?',
    options: ['When ink soaks through to the reverse side', 'Extending artwork beyond the trim edge (typically 3mm) so that after trimming there are no white edges where cutting is slightly off-register', 'A type of paper texture', 'Over-inking that causes smudging'],
    answer: '1',
