    text: 'What is the difference between raster (bitmap) and vector graphics?',
    options: ['They are the same format', 'Raster images are made of pixels and lose quality when enlarged; vector graphics use mathematical paths/shapes and scale to any size without loss of quality', 'Raster images are always black and white; vector images are always in colour', 'Only raster images can be printed'],
    answer: '1',
