    explanation: 'Freehand sketching is the designer\'s primary tool for thinking on paper: it is fast, requires no setup, can capture any idea in seconds, and communicates concept to others. Sketching before technical drawing filters good ideas from bad before investing detailed effort. It is not about perfection — it is about speed of exploration.',
