    answer: '1',
    explanation: 'Isometric drawing: three axes (x, y, z) drawn at 120° to each other, typically with one axis vertical. All parallel lines remain parallel (no vanishing points) and all measurements along the axes are true scale. Ideal for showing 3D objects clearly without distorting dimensions — used in product design and engineering.',
