    text: 'What is the purpose of presenting design ideas using "crating" in freehand sketching?',
    options: ['To add a decorative box around the drawing', 'A sketching technique where a 3D box (crate) is drawn first to establish proportions and orientation of a product in 3D, then the product shape is drawn within this box — keeping proportions correct', 'A method of packaging a product', 'A construction technique for models'],
