    text: 'What are the Gestalt principles used in graphic design?',
    options: ['A set of rules about colour mixing', 'A set of psychological principles describing how humans perceive visual elements as organised groups — including proximity, similarity, continuation, closure, and figure-ground', 'A manufacturing standard for print', 'A set of typography sizing rules'],
