    text: 'What is 3D printing (additive manufacturing) and how does FDM (Fused Deposition Modelling) work?',
    options: ['Printing three-dimensional text on a flat surface', 'A process that builds physical objects layer by layer from a digital file; FDM works by melting a plastic filament and extruding it layer by layer until the 3D shape is complete', 'A two-sided printing process', 'A form of die cutting for 3D shapes'],
    answer: '1',
