    text: 'What is a vinyl cutter and how is it used in Graphic Products?',
    options: ['A tool for cutting vinyl records', 'A computer-controlled machine with a small blade that cuts self-adhesive vinyl sheet to produce letters, logos, shapes, and designs — used for signage, vehicle graphics, and stickers', 'A machine that melts vinyl into shapes', 'A type of laser cutter that only works on vinyl'],
