    text: 'What is a USP (Unique Selling Point) in product design and marketing?',
    options: ['The universal safety protocol for a product', 'A feature or quality that differentiates a product from competitors — the specific reason why a customer would choose this product over all alternatives', 'The patent number of a design', 'The maximum units a product can sell'],
