    text: 'What is smart packaging and how does technology make packaging interactive?',
    options: ['Packaging that is easy to open', 'Packaging with embedded digital features: NFC chips (tap with phone to access content), RFID tracking, temperature indicators, QR codes, AR triggers, conductive inks for touch-sensitive surfaces, and freshness sensors — connecting physical packaging to digital experiences', 'Packaging designed using a computer', 'Packaging with smart visual design only'],
