    options: ['Two identical products manufactured digitally', 'A precise virtual replica of a physical product, process, or system — updated with real-time data — used to simulate performance, test design changes, and predict manufacturing issues before physical production begins, reducing costly physical prototyping', 'A digital backup of a design file', 'Two computers working together on one design project'],
    answer: '1',
