    text: 'What is automation in graphic design and printing, and what tasks does it handle?',
    options: ['Automation only applies to industrial manufacturing', 'Computer-controlled processes that handle repetitive tasks without human intervention: automated prepress checks (preflight); variable data printing (personalising each copy); automated file sorting and colour separation; batch processing of images; automated imposition (arranging multiple pages on press sheets)', 'Automation completely replaces designers in the near term', 'Only relevant to typesetting'],
