    options: ['Technology has completely replaced graphic designers', 'Technology has expanded the scope of graphic design: new output types (digital, interactive, motion); more powerful tools enabling complex output; some technical tasks automated (prepress checks, file preparation); new skills required (digital, coding knowledge); the role has shifted toward concept, strategy, and user experience rather than production', 'Technology has made design skills less important', 'Technology has only changed output formats, not the design process itself'],
    answer: '1',
